#include "aisoc_dbus.h"
#include "aisoc_dbus_internal.h"

aisoc_dbus_status_t aisoc_dbus_send_message(
    aisoc_dbus_conn_t* conn,
    aisoc_dbus_msg_t*  msg
) {
    if (conn == nullptr || msg == nullptr) {
        return AISOC_DBUS_ERR_NULL_PTR;
    }
    const bool valid_conn = (conn->conn != nullptr && conn->is_connected);
    const bool valid_msg = (msg->msg != nullptr);
    if (!valid_conn || !valid_msg) {
        return AISOC_DBUS_ERR_INVALID_PARAM;
    }

    dbus_bool_t sent = dbus_connection_send(conn->conn, msg->msg, nullptr);
    if (!sent) {
        return AISOC_DBUS_ERR_INTERNAL;
    }
    dbus_connection_flush(conn->conn);
    return AISOC_DBUS_OK;
}

static aisoc_dbus_status_t aisoc_dbus_handle_call_error(
    DBusError* d_err
) {
    aisoc_dbus_status_t st = aisoc_dbus_map_dbus_error(d_err);
    dbus_error_free(d_err);
    return st;
}

static aisoc_dbus_status_t aisoc_dbus_handle_reply_error(
    DBusMessage*      raw_reply,
    aisoc_dbus_msg_t* reply
) {
    reply->msg = raw_reply;
    reply->msg_type = DBUS_MESSAGE_TYPE_ERROR;
    const char* err_name = dbus_message_get_error_name(raw_reply);
    if (err_name == nullptr) {
        return AISOC_DBUS_ERR_INTERNAL;
    }
    aisoc_dbus_status_t st = AISOC_DBUS_ERR_INTERNAL;
    aisoc_dbus_status_from_name(err_name, &st);
    return st;
}

aisoc_dbus_status_t aisoc_dbus_call_method(
    aisoc_dbus_conn_t*            conn,
    const aisoc_dbus_msg_t*       req,
    const aisoc_dbus_call_opts_t* opts,
    aisoc_dbus_msg_t*             reply
) {
    if (conn == nullptr || req == nullptr || reply == nullptr) {
        return AISOC_DBUS_ERR_NULL_PTR;
    }
    reply->msg = nullptr;
    reply->msg_type = 0;
    const bool valid_conn = (conn->conn != nullptr && conn->is_connected);
    const bool valid_req = (req->msg != nullptr);
    if (!valid_conn || !valid_req) {
        return AISOC_DBUS_ERR_INVALID_PARAM;
    }

    int timeout = 200;
    if (opts != nullptr && opts->timeout_ms > 0) {
        timeout = opts->timeout_ms;
    }

    DBusError d_err;
    dbus_error_init(&d_err);
    DBusMessage* raw_reply = dbus_connection_send_with_reply_and_block(
        conn->conn,
        req->msg,
        timeout,
        &d_err
    );
    if (dbus_error_is_set(&d_err)) {
        return aisoc_dbus_handle_call_error(&d_err);
    }
    if (raw_reply == nullptr) {
        return AISOC_DBUS_ERR_NO_REPLY;
    }

    int m_type = dbus_message_get_type(raw_reply);
    if (m_type == DBUS_MESSAGE_TYPE_ERROR) {
        return aisoc_dbus_handle_reply_error(raw_reply, reply);
    }
    reply->msg = raw_reply;
    reply->msg_type = DBUS_MESSAGE_TYPE_METHOD_RETURN;
    return AISOC_DBUS_OK;
}
/**
