aisoc_dbus_status_t aisoc_dbus_register_interface(
    aisoc_dbus_conn_t*                  conn,
    const aisoc_dbus_interface_entry_t* iface_entry
) {
    if (conn == nullptr || iface_entry == nullptr) {
        return AISOC_DBUS_ERR_NULL_PTR;
    }
    const bool valid_path = (iface_entry->path != nullptr);
    const bool valid_iface = (iface_entry->interface_name != nullptr);
    if (!valid_path || !valid_iface) {
        return AISOC_DBUS_ERR_INVALID_PARAM;
    }
    if (conn->interface_count >= AISOC_DBUS_MAX_INTERFACES) {
        return AISOC_DBUS_ERR_BUFFER_OVERFLOW;
    }
    conn->interfaces[conn->interface_count] = *iface_entry;
    conn->interface_count++;
    return AISOC_DBUS_OK;
}

static aisoc_dbus_status_t aisoc_dbus_format_match_rule(
    const aisoc_dbus_signal_entry_t* sig_entry,
    char*                            buf,
    size_t                           buf_len
) {
    if (sig_entry == nullptr || buf == nullptr) {
        return AISOC_DBUS_ERR_NULL_PTR;
    }
    const char* iface = sig_entry->interface_name;
    const char* member = sig_entry->signal_name;
    int written = 0;
    if (sig_entry->path != nullptr && strlen(sig_entry->path) > 0) {
        written = snprintf(
            buf,
            buf_len,
            "type='signal',interface='%s',member='%s',path='%s'",
            iface,
            member,
            sig_entry->path
        );
    } else {
        written = snprintf(
            buf,
            buf_len,
            "type='signal',interface='%s',member='%s'",
            iface,
            member
        );
    }
    if (written < 0 || static_cast<size_t>(written) >= buf_len) {
        return AISOC_DBUS_ERR_BUFFER_OVERFLOW;
    }
    return AISOC_DBUS_OK;
}

aisoc_dbus_status_t aisoc_dbus_subscribe_signal(
    aisoc_dbus_conn_t*               conn,
    const aisoc_dbus_signal_entry_t* sig_entry
) {
    if (conn == nullptr || sig_entry == nullptr) {
        return AISOC_DBUS_ERR_NULL_PTR;
    }
    const bool valid_conn = (conn->conn != nullptr && conn->is_connected);
    const bool valid_sub = (sig_entry->interface_name != nullptr && sig_entry->signal_name != nullptr);
    if (!valid_conn || !valid_sub) {
        return AISOC_DBUS_ERR_INVALID_PARAM;
    }
    if (conn->signal_count >= AISOC_DBUS_MAX_SIGNALS) {
        return AISOC_DBUS_ERR_BUFFER_OVERFLOW;
    }

    char match_buf[256];
    aisoc_dbus_status_t fmt_st = aisoc_dbus_format_match_rule(sig_entry, match_buf, sizeof(match_buf));
    if (fmt_st != AISOC_DBUS_OK) {
        return fmt_st;
    }

    DBusError d_err;
    dbus_error_init(&d_err);
    dbus_bus_add_match(conn->conn, match_buf, &d_err);
    if (dbus_error_is_set(&d_err)) {
        aisoc_dbus_status_t st = aisoc_dbus_map_dbus_error(&d_err);
        dbus_error_free(&d_err);
        return st;
    }

    conn->signals[conn->signal_count] = *sig_entry;
    conn->signal_count++;
    return AISOC_DBUS_OK;
}

static DBusHandlerResult aisoc_dbus_handle_introspect(
    DBusConnection* raw_conn,
    DBusMessage*    raw_msg,
    const char*     path
) {
    const char* xml = nullptr;
    if (strcmp(path, AISOC_DBUS_PATH_FORWARD) == 0) {
        xml = kIntrospectForward;
    } else if (strcmp(path, AISOC_DBUS_PATH_DEVICE) == 0) {
        xml = kIntrospectDevice;
    } else if (strcmp(path, AISOC_DBUS_PATH_HMS) == 0) {
        xml = kIntrospectHms;
    }
    if (xml == nullptr) {
        return DBUS_HANDLER_RESULT_NOT_YET_HANDLED;
    }
    DBusMessage* reply = dbus_message_new_method_return(raw_msg);
    if (reply == nullptr) {
        return DBUS_HANDLER_RESULT_NEED_MEMORY;
    }
    DBusMessageIter iter;
    dbus_message_iter_init_append(reply, &iter);
    dbus_message_iter_append_basic(&iter, DBUS_TYPE_STRING, &xml);
    dbus_connection_send(raw_conn, reply, nullptr);
    dbus_connection_flush(raw_conn);
    dbus_message_unref(reply);
    return DBUS_HANDLER_RESULT_HANDLED;
}

static DBusHandlerResult aisoc_dbus_execute_method(
    DBusConnection*                  raw_conn,
    DBusMessage*                     raw_msg,
    const aisoc_dbus_method_entry_t* method_entry,
    void*                            user_data
) {
    aisoc_dbus_msg_t req = { raw_msg, DBUS_MESSAGE_TYPE_METHOD_CALL };
    aisoc_dbus_msg_t reply;
    aisoc_dbus_status_t init_st = aisoc_dbus_msg_init_reply(&req, &reply);
    if (init_st != AISOC_DBUS_OK) {
        return DBUS_HANDLER_RESULT_NEED_MEMORY;
    }

    aisoc_dbus_status_t h_st = method_entry->handler(&req, &reply, user_data);
    if (h_st != AISOC_DBUS_OK) {
        aisoc_dbus_msg_unref(&reply);
        const char* err_name = nullptr;
        aisoc_dbus_status_to_name(h_st, &err_name);
        DBusMessage* err_msg = dbus_message_new_error(raw_msg, err_name, "Method invocation failed");
        if (err_msg != nullptr) {
            dbus_connection_send(raw_conn, err_msg, nullptr);
            dbus_connection_flush(raw_conn);
            dbus_message_unref(err_msg);
        }
        return DBUS_HANDLER_RESULT_HANDLED;
    }

    dbus_connection_send(raw_conn, reply.msg, nullptr);
    dbus_connection_flush(raw_conn);
    aisoc_dbus_msg_unref(&reply);
    return DBUS_HANDLER_RESULT_HANDLED;
}

static DBusHandlerResult aisoc_dbus_find_and_exec_method(
    DBusConnection*                     raw_conn,
    DBusMessage*                        raw_msg,
    const aisoc_dbus_interface_entry_t* iface,
    const char*                         member
) {
    for (size_t j = 0; j < iface->method_count; ++j) {
        const aisoc_dbus_method_entry_t* cur_m = &iface->methods[j];
        const bool match_name = (cur_m->method_name != nullptr && strcmp(cur_m->method_name, member) == 0);
        if (match_name) {
            return aisoc_dbus_execute_method(raw_conn, raw_msg, cur_m, iface->user_data);
        }
    }
    return DBUS_HANDLER_RESULT_NOT_YET_HANDLED;
}

static DBusHandlerResult aisoc_dbus_dispatch_method(
    DBusConnection*    raw_conn,
    DBusMessage*       raw_msg,
    aisoc_dbus_conn_t* conn
) {
    const char* path = dbus_message_get_path(raw_msg);
    const char* iface = dbus_message_get_interface(raw_msg);
    const char* member = dbus_message_get_member(raw_msg);
    if (path == nullptr || member == nullptr) {
        return DBUS_HANDLER_RESULT_NOT_YET_HANDLED;
    }

    if (iface != nullptr && strcmp(iface, "org.freedesktop.DBus.Introspectable") == 0 &&
        strcmp(member, "Introspect") == 0) {
        return aisoc_dbus_handle_introspect(raw_conn, raw_msg, path);
    }

    for (size_t i = 0; i < conn->interface_count; ++i) {
        const aisoc_dbus_interface_entry_t* cur_iface = &conn->interfaces[i];
        const bool match_path = (strcmp(cur_iface->path, path) == 0);
        const bool match_iface = (iface != nullptr && strcmp(cur_iface->interface_name, iface) == 0);
        if (match_path && match_iface) {
            DBusHandlerResult res = aisoc_dbus_find_and_exec_method(raw_conn, raw_msg, cur_iface, member);
            if (res != DBUS_HANDLER_RESULT_NOT_YET_HANDLED) {
                return res;
            }
        }
    }
    return DBUS_HANDLER_RESULT_NOT_YET_HANDLED;
}

