static bool test_error_forward() {
    aisoc_dbus_status_t st = AISOC_DBUS_ERR_INTERNAL;
    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_NONE, &st);
    TEST_CHECK(st == AISOC_DBUS_OK, "None error map");

    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_TIMEOUT, &st);
    TEST_CHECK(st == AISOC_DBUS_ERR_TIMEOUT, "Timeout error map");

    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_INVALID_ARG, &st);
    TEST_CHECK(st == AISOC_DBUS_ERR_INVALID_PARAM, "InvalidArgument error map");

    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_BUSY, &st);
    TEST_CHECK(st == AISOC_DBUS_ERR_DEVICE_BUSY, "DeviceBusy error map");

    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_CRC, &st);
    TEST_CHECK(st == AISOC_DBUS_ERR_CRC_MISMATCH, "CrcMismatch error map");

    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_ESTOP, &st);
    TEST_CHECK(st == AISOC_DBUS_ERR_EMERGENCY_STOP, "EmergencyStopped error map");
    return true;
}

static bool test_error_reverse() {
    const char* name = nullptr;
    aisoc_dbus_status_to_name(AISOC_DBUS_OK, &name);
    TEST_CHECK(strcmp(name, AISOC_DBUS_ERR_NAME_NONE) == 0, "OK to name");

    aisoc_dbus_status_to_name(AISOC_DBUS_ERR_TIMEOUT, &name);
    TEST_CHECK(strcmp(name, AISOC_DBUS_ERR_NAME_TIMEOUT) == 0, "Timeout to name");

    aisoc_dbus_status_to_name(AISOC_DBUS_ERR_INVALID_PARAM, &name);
    TEST_CHECK(strcmp(name, AISOC_DBUS_ERR_NAME_INVALID_ARG) == 0, "Invalid to name");

    aisoc_dbus_status_to_name(AISOC_DBUS_ERR_DEVICE_BUSY, &name);
    TEST_CHECK(strcmp(name, AISOC_DBUS_ERR_NAME_BUSY) == 0, "Busy to name");

    aisoc_dbus_status_to_name(AISOC_DBUS_ERR_EMERGENCY_STOP, &name);
    TEST_CHECK(strcmp(name, AISOC_DBUS_ERR_NAME_ESTOP) == 0, "Estop to name");
    return true;
}

